def chain_follows_chain(chain):
    chain = list(chain)
    chain.reverse()
    result = []
    for i in range(len(chain)):
        result.append(chain[i])
        if i == len(chain) - 1:
            break
        next_item = chain[i + 1]
        if next_item == chain[i]:
            break
        result.append(next_item)
    return ','.join(result)

